#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."
project_root="$PWD"
mkdir -p builds
# Generate app-only configuration without printing credentials. The generated file is ignored.
python3 - <<'PYCONFIG'
import json
import os
import pathlib
import sys
from urllib.parse import urlparse

root = pathlib.Path.cwd()
backend_path = root / "Config/Backend.json"
accounts_path = root / "Config/TestAccounts.json"
output = root / "WeaveApp/Services/LocalConfiguration.swift"
if not backend_path.is_file():
    sys.exit("Missing Config/Backend.json. Configure the Supabase project before building; see README.md.")
try:
    backend = json.loads(backend_path.read_text())
    base_url = backend["url"]
    anon_key = backend["anonKey"]
    parsed = urlparse(base_url)
    if parsed.scheme != "https" or not parsed.hostname or not isinstance(anon_key, str) or not anon_key:
        raise ValueError()
    if anon_key.startswith("sb_secret_"):
        sys.exit("Config/Backend.json must use a public anon/publishable key, never a secret/service-role key.")
    # Legacy Supabase JWT keys encode their role in the payload.
    if anon_key.count(".") == 2:
        import base64
        payload = anon_key.split(".")[1]
        claims = json.loads(base64.urlsafe_b64decode(payload + "=" * (-len(payload) % 4)))
        if claims.get("role") != "anon":
            sys.exit("Config/Backend.json JWT must have role anon; service-role keys cannot be embedded in the app.")
except (KeyError, ValueError, TypeError):
    sys.exit("Config/Backend.json must contain a valid HTTPS url and public anonKey.")

# JSON string escaping also escapes backslashes, preventing Swift interpolation.
def swift_string(value):
    return json.dumps(value, ensure_ascii=False)

lines = ["// Generated by Scripts/build-sim.sh. Do not commit this file.",
         "enum LocalConfiguration {",
         "    static let url = " + swift_string(base_url.rstrip("/")),
         "    static let anonKey = " + swift_string(anon_key),
         "    #if DEBUG",
         "    struct TestAccount { let email: String; let password: String }",
         "    static let testAccounts: [String: TestAccount] = ["]
if accounts_path.is_file():
    try:
        accounts = json.loads(accounts_path.read_text())
        for name in ("alice", "bob", "charlie"):
            account = accounts[name]
            if not all(isinstance(account[k], str) and account[k] for k in ("email", "password")):
                raise ValueError()
            lines.append("        " + swift_string(name) + ": TestAccount(email: " + swift_string(account["email"]) + ", password: " + swift_string(account["password"]) + "),")
    except (KeyError, ValueError, TypeError):
        sys.exit("Config/TestAccounts.json must have alice, bob, and charlie objects with email/password strings.")
else:
    lines.append("        :")
    print("No Config/TestAccounts.json: Debug account shortcut buttons will report missing configuration.", file=sys.stderr)
lines.extend(["    ]", "    #endif", "}", ""])
output.write_text("\n".join(lines))
os.chmod(output, 0o600)
PYCONFIG
xcodebuild -scheme Weave -sdk iphonesimulator -configuration Debug -derivedDataPath build
app_path="build/Build/Products/Debug-iphonesimulator/Weave.app"
if [[ ! -d "$app_path" ]]; then
  echo "Build did not produce $app_path" >&2
  exit 1
fi
rm -f builds/Weave.zip
(cd "$(dirname "$app_path")" && /usr/bin/zip -qr "$project_root/builds/Weave.zip" Weave.app)
echo "Simulator app: builds/Weave.zip"
